Account.ready.then(user=>{
 if(user.role!=='admin'){location.replace('/sets.html');return}
 const $=id=>document.getElementById(id);let preview=null,busy=false;
 function message(t){$('sync-message').textContent=t}
 function lock(value){busy=value;for(const id of ['download-master','preview-sync','sync-file'])$(id).disabled=value;$('commit-sync').disabled=value||!preview}
 async function status(){try{const r=await Account.request('/api/admin/excel-status');$('last-sync').textContent=r.created?'Last successful sync: '+new Date(r.created).toLocaleString()+' · '+r.counts.Add+' added, '+r.counts.Update+' updated, '+r.counts.Archive+' archived.':'No Excel sync has been completed yet.'}catch(e){$('last-sync').textContent=e.message}}
 $('download-master').onclick=async()=>{lock(true);message('Preparing workbook…');try{const r=await fetch('/api/admin/master.xlsx');if(!r.ok)throw Error((await r.json()).error||'Download failed.');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=/filename="([^"]+)"/.exec(r.headers.get('Content-Disposition')||'')?.[1]||'Master_excel.xlsx' ;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Workbook downloaded. Edit it in Excel, then upload it here.')}catch(e){message(e.message)}finally{lock(false)}};
 $('sync-file').onchange=()=>{preview=null;$('commit-sync').disabled=true;$('sync-review').hidden=true;message('')};
 $('preview-sync').onclick=async()=>{const file=$('sync-file').files[0];if(!file||!file.name.toLowerCase().endsWith('.xlsx')||file.size>8*1024*1024){message('Choose an .xlsx workbook under 8 MB.');return}preview=null;lock(true);message('Reading and validating workbook…');try{const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const result=await Account.request('/api/admin/excel-preview',{file:encoded});$('sync-review').hidden=false;$('sync-summary').textContent=result.changes.length+' proposed changes · '+result.unchanged+' unchanged rows · '+result.errors.length+' errors.';$('sync-errors').replaceChildren();for(const e of result.errors){const li=document.createElement('li');li.textContent='Row '+e.row+' · '+e.id+': '+e.message;$('sync-errors').append(li)}$('sync-changes').replaceChildren();for(const c of result.changes){const box=document.createElement('details');box.className='change';const title=document.createElement('summary');title.textContent=c.action+' '+c.id+' · Excel row '+c.row;box.append(title);for(const key of Object.keys(c.after)){if(c.before&&JSON.stringify(c.before[key])===JSON.stringify(c.after[key]))continue;const p=document.createElement('pre');p.textContent=key+': '+(c.before?JSON.stringify(c.before[key])+' → ':'')+JSON.stringify(c.after[key]);box.append(p)}$('sync-changes').append(box)}preview=result.preview_id;message(result.errors.length?'Correct the errors in Excel and upload again. Nothing has been saved.':preview?'Review the proposed changes, then confirm.':'No changes to save.');}catch(e){message(e.message)}finally{lock(false)}};
 $('commit-sync').onclick=async()=>{if(!preview||busy)return;lock(true);message('Creating backup and applying sync…');try{const r=await Account.request('/api/admin/excel-commit',{preview_id:preview});preview=null;message('Sync complete: '+r.counts.Add+' added, '+r.counts.Update+' updated, '+r.counts.Archive+' archived. Backup verified. Download a fresh workbook before editing again.');await status()}catch(e){message(e.message)}finally{lock(false)}};
 window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue=''}});status();
}).catch(()=>{});
